        public static long PartRowFixedMeasure(long count)
        {
            return TableFixedWire.HeaderBytes + 4 + PartRowFixedLayoutBytes + count * PartRowFixedRecordBytes;
        }

        public static long PartRowFixedSave(ReadOnlySpan<PartRow> values, Span<byte> buffer)
        {
            long need = PartRowFixedMeasure(values.Length);
            if (values.Length < 0 || buffer.Length < need) { return -1; }
            buffer.Slice(0, TableFixedWire.HeaderBytes).Clear();
            buffer[0] = TableFixedWire.Form;
            BinaryPrimitives.WriteUInt64LittleEndian(buffer.Slice(TableFixedWire.HashAt), PartRowFixedHash);
            BinaryPrimitives.WriteUInt32LittleEndian(buffer.Slice(TableFixedWire.HeaderBytes), (uint)PartRowFixedLayoutBytes);
            PartRowFixedLayout.CopyTo(buffer.Slice(TableFixedWire.HeaderBytes + 4));
            Span<byte> at = buffer.Slice(TableFixedWire.HeaderBytes + 4 + (int)PartRowFixedLayoutBytes);
            for (int k = 0; k < values.Length; ++k)
            {
                BinaryPrimitives.WriteUInt64LittleEndian(at, PartRowFixedHash);
                at.Slice(8, (int)PartRowFixedBodyBytes).Clear();
                PartRowFixedWriteBody(at.Slice(8), values[k]);
                at = at.Slice((int)PartRowFixedRecordBytes);
            }
            return need;
        }

        public static long PartRowFixedSave(PartRow[] values, Span<byte> buffer)
        {
            return PartRowFixedSave((ReadOnlySpan<PartRow>)values, buffer);
        }

        public static long PartRowFixedSave(PartRow value, Span<byte> buffer)
        {
            ReadOnlySpan<PartRow> span = MemoryMarshal.CreateReadOnlySpan(ref value, 1);
            return PartRowFixedSave(span, buffer);
        }

        public static long PartRowFixedLoad(
            Span<PartRow> values,
            ReadOnlySpan<byte> data,
            Span<TableFixedEntry> plan,
            TableReport report = null)
        {
            if (data.Length < TableFixedWire.HeaderBytes + 4)
            {
                if (report != null) { report.Malformed = true; report.Verdict = TableWire.Verdict.Damaged; }
                return -1;
            }
            if (data[0] != TableFixedWire.Form)
            {
                if (report != null)
                {
                    report.Refused = true;
                    report.Reason = data[0] == 2 ? "message_form_as_file"
                                  : data[0] < TableFixedWire.Form ? "previous_form"
                                  : "newer_form";
                    report.Verdict = TableWire.Verdict.Refused;
                }
                return -1;
            }
            uint layout_bytes = BinaryPrimitives.ReadUInt32LittleEndian(data.Slice(TableFixedWire.HeaderBytes));
            if ((long)layout_bytes + TableFixedWire.HeaderBytes + 4 > data.Length)
            {
                if (report != null) { report.Refused = true; report.Reason = "layout_malformed"; report.Verdict = TableWire.Verdict.Refused; }
                return -1;
            }
            ReadOnlySpan<byte> layout = data.Slice(TableFixedWire.HeaderBytes + 4, (int)layout_bytes);
            ulong hash = TableFixedWire.HashOf(layout);
            ReadOnlySpan<byte> at = data.Slice(TableFixedWire.HeaderBytes + 4 + (int)layout_bytes);
            int rest = data.Length - TableFixedWire.HeaderBytes - 4 - (int)layout_bytes;
            ReadOnlySpan<TableFixedEntry> entries = PartRowFixedPlan;
            long record_bytes = PartRowFixedRecordBytes;
            ReadOnlySpan<byte> planBytes = ReadOnlySpan<byte>.Empty;
            TableFixedFill[] fillBuf = Array.Empty<TableFixedFill>();
            int fillCount = 0;
            if (hash != PartRowFixedHash)
            {
                if (!TableFixedWire.ParseLayout(layout, out TableFixedLayoutView parsed, out string why))
                {
                    if (report != null) { report.Refused = true; report.Reason = why; report.Verdict = TableWire.Verdict.Refused; }
                    return -1;
                }
                int made = TableFixedWire.Compile(parsed, PartRowFixedLayout, PartRowFixedDst, plan, report);
                if (made < 0)
                {
                    if (report != null) { report.Refused = true; report.Reason = "plan_too_large"; report.Verdict = TableWire.Verdict.Refused; }
                    return -1;
                }
                entries = plan.Slice(0, made);
                record_bytes = 8 + (long)TableFixedWire.EntryAt(parsed, 0).Size;
                planBytes = MemoryMarshal.AsBytes(plan);
                int slotN = PartRowFixedSlots.Length;
                if (slotN > 0)
                {
                    byte[] landed = new byte[slotN];
                    fillBuf = new TableFixedFill[slotN];
                    fillCount = TableFixedWire.Fills(entries, PartRowFixedCover, landed, fillBuf);
                }
            }
            if (BinaryPrimitives.ReadUInt64LittleEndian(data.Slice(TableFixedWire.HashAt)) != hash)
            {
                if (report != null) { report.Refused = true; report.Reason = "layout_malformed"; report.Verdict = TableWire.Verdict.Refused; }
                return -1;
            }
            if (record_bytes <= 8 || rest % record_bytes != 0)
            {
                if (report != null) { report.Malformed = true; report.Verdict = TableWire.Verdict.Damaged; }
                return -1;
            }
            long n = rest / record_bytes;
            if (n > values.Length)
            {
                if (report != null) { report.Refused = true; report.Reason = "batch_too_large"; report.Verdict = TableWire.Verdict.Refused; }
                return -1;
            }
            // ONE RECORD LOOP. Prefill the holes, walk the plan. Empty list is the
            // skip: identity's fill is empty, so this read writes no slot twice.
            for (int k = 0; k < n; ++k)
            {
                if (values[k] == null) { values[k] = new PartRow(); }
                TableFixedWire.FillRun(fillBuf.AsSpan(0, fillCount), PartRowFixedSlots, values[k]);
                if (BinaryPrimitives.ReadUInt64LittleEndian(at) != hash)
                {
                    if (report != null) { report.Refused = true; report.Reason = "no_layout"; report.Verdict = TableWire.Verdict.Refused; }
                    return -1;
                }
                TableFixedWire.Run(entries, PartRowFixedSlots, at.Slice(8), values[k], report, planBytes);
                at = at.Slice((int)record_bytes);
            }
            if (report != null) { report.Verdict = TableWire.Verdict.Ok; }
            return n;
        }

        public static long PartRowFixedLoad(PartRow[] values, ReadOnlySpan<byte> data, Span<TableFixedEntry> plan, TableReport report = null)
        {
            return PartRowFixedLoad((Span<PartRow>)values, data, plan, report);
        }

        public static long PartRowFixedLoad(PartRow value, ReadOnlySpan<byte> data, Span<TableFixedEntry> plan, TableReport report = null)
        {
            Span<PartRow> span = MemoryMarshal.CreateSpan(ref value, 1);
            return PartRowFixedLoad(span, data, plan, report);
        }

        public static void TableFixedRun(
            ReadOnlySpan<TableFixedEntry> plan,
            ReadOnlySpan<byte> src,
            PartRow dst,
            TableReport report = null,
            ReadOnlySpan<byte> planBytes = default)
        {
            TableFixedWire.Run(plan, PartRowFixedSlots, src, dst, report, planBytes);
        }

