        public static long PartFrameFixedMeasure(long count)
        {
            return TableFixedWire.HeaderBytes + 4 + PartFrameFixedLayoutBytes + count * PartFrameFixedRecordBytes;
        }

        public static long PartFrameFixedSave(ReadOnlySpan<PartFrame> values, Span<byte> buffer)
        {
            long need = PartFrameFixedMeasure(values.Length);
            if (values.Length < 0 || buffer.Length < need) { return -1; }
            buffer.Slice(0, TableFixedWire.HeaderBytes).Clear();
            buffer[0] = TableFixedWire.Form;
            BinaryPrimitives.WriteUInt64LittleEndian(buffer.Slice(TableFixedWire.HashAt), PartFrameFixedHash);
            BinaryPrimitives.WriteUInt32LittleEndian(buffer.Slice(TableFixedWire.HeaderBytes), (uint)PartFrameFixedLayoutBytes);
            PartFrameFixedLayout.CopyTo(buffer.Slice(TableFixedWire.HeaderBytes + 4));
            Span<byte> at = buffer.Slice(TableFixedWire.HeaderBytes + 4 + (int)PartFrameFixedLayoutBytes);
            for (int k = 0; k < values.Length; ++k)
            {
                BinaryPrimitives.WriteUInt64LittleEndian(at, PartFrameFixedHash);
                at.Slice(8, (int)PartFrameFixedBodyBytes).Clear();
                PartFrameFixedWriteBody(at.Slice(8), values[k]);
                at = at.Slice((int)PartFrameFixedRecordBytes);
            }
            return need;
        }

        public static long PartFrameFixedSave(PartFrame[] values, Span<byte> buffer)
        {
            return PartFrameFixedSave((ReadOnlySpan<PartFrame>)values, buffer);
        }

        public static long PartFrameFixedSave(PartFrame value, Span<byte> buffer)
        {
            ReadOnlySpan<PartFrame> span = MemoryMarshal.CreateReadOnlySpan(ref value, 1);
            return PartFrameFixedSave(span, buffer);
        }

        public static long PartFrameFixedLoad(
            Span<PartFrame> values,
            ReadOnlySpan<byte> data,
            Span<TableFixedEntry> plan,
            TableReport report = null)
        {
            if (data.Length < TableFixedWire.HeaderBytes + 4)
            {
                if (report != null) { report.Malformed = true; report.Verdict = TableWire.Verdict.Damaged; }
                return -1;
            }
            if (data[0] != TableFixedWire.Form)
            {
                if (report != null)
                {
                    report.Refused = true;
                    report.Reason = data[0] == 2 ? "message_form_as_file"
                                  : data[0] < TableFixedWire.Form ? "previous_form"
                                  : "newer_form";
                    report.Verdict = TableWire.Verdict.Refused;
                }
                return -1;
            }
            uint layout_bytes = BinaryPrimitives.ReadUInt32LittleEndian(data.Slice(TableFixedWire.HeaderBytes));
            if ((long)layout_bytes + TableFixedWire.HeaderBytes + 4 > data.Length)
            {
                if (report != null) { report.Refused = true; report.Reason = "layout_malformed"; report.Verdict = TableWire.Verdict.Refused; }
                return -1;
            }
            ReadOnlySpan<byte> layout = data.Slice(TableFixedWire.HeaderBytes + 4, (int)layout_bytes);
            ulong hash = TableFixedWire.HashOf(layout);
            ReadOnlySpan<byte> at = data.Slice(TableFixedWire.HeaderBytes + 4 + (int)layout_bytes);
            int rest = data.Length - TableFixedWire.HeaderBytes - 4 - (int)layout_bytes;
            ReadOnlySpan<TableFixedEntry> entries = PartFrameFixedPlan;
            long record_bytes = PartFrameFixedRecordBytes;
            ReadOnlySpan<byte> planBytes = ReadOnlySpan<byte>.Empty;
            TableFixedFill[] fillBuf = Array.Empty<TableFixedFill>();
            int fillCount = 0;
            if (hash != PartFrameFixedHash)
            {
                if (!TableFixedWire.ParseLayout(layout, out TableFixedLayoutView parsed, out string why))
                {
                    if (report != null) { report.Refused = true; report.Reason = why; report.Verdict = TableWire.Verdict.Refused; }
                    return -1;
                }
                int made = TableFixedWire.Compile(parsed, PartFrameFixedLayout, PartFrameFixedDst, plan, report);
                if (made < 0)
                {
                    if (report != null) { report.Refused = true; report.Reason = "plan_too_large"; report.Verdict = TableWire.Verdict.Refused; }
                    return -1;
                }
                entries = plan.Slice(0, made);
                record_bytes = 8 + (long)TableFixedWire.EntryAt(parsed, 0).Size;
                planBytes = MemoryMarshal.AsBytes(plan);
                int slotN = PartFrameFixedSlots.Length;
                if (slotN > 0)
                {
                    byte[] landed = new byte[slotN];
                    fillBuf = new TableFixedFill[slotN];
                    fillCount = TableFixedWire.Fills(entries, PartFrameFixedCover, landed, fillBuf);
                }
            }
            if (BinaryPrimitives.ReadUInt64LittleEndian(data.Slice(TableFixedWire.HashAt)) != hash)
            {
                if (report != null) { report.Refused = true; report.Reason = "layout_malformed"; report.Verdict = TableWire.Verdict.Refused; }
                return -1;
            }
            if (record_bytes <= 8 || rest % record_bytes != 0)
            {
                if (report != null) { report.Malformed = true; report.Verdict = TableWire.Verdict.Damaged; }
                return -1;
            }
            long n = rest / record_bytes;
            if (n > values.Length)
            {
                if (report != null) { report.Refused = true; report.Reason = "batch_too_large"; report.Verdict = TableWire.Verdict.Refused; }
                return -1;
            }
            // ONE RECORD LOOP. Prefill the holes, walk the plan. Empty list is the
            // skip: identity's fill is empty, so this read writes no slot twice.
            for (int k = 0; k < n; ++k)
            {
                if (values[k] == null) { values[k] = new PartFrame(); }
                TableFixedWire.FillRun(fillBuf.AsSpan(0, fillCount), PartFrameFixedSlots, values[k]);
                if (BinaryPrimitives.ReadUInt64LittleEndian(at) != hash)
                {
                    if (report != null) { report.Refused = true; report.Reason = "no_layout"; report.Verdict = TableWire.Verdict.Refused; }
                    return -1;
                }
                TableFixedWire.Run(entries, PartFrameFixedSlots, at.Slice(8), values[k], report, planBytes);
                at = at.Slice((int)record_bytes);
            }
            if (report != null) { report.Verdict = TableWire.Verdict.Ok; }
            return n;
        }

        public static long PartFrameFixedLoad(PartFrame[] values, ReadOnlySpan<byte> data, Span<TableFixedEntry> plan, TableReport report = null)
        {
            return PartFrameFixedLoad((Span<PartFrame>)values, data, plan, report);
        }

        public static long PartFrameFixedLoad(PartFrame value, ReadOnlySpan<byte> data, Span<TableFixedEntry> plan, TableReport report = null)
        {
            Span<PartFrame> span = MemoryMarshal.CreateSpan(ref value, 1);
            return PartFrameFixedLoad(span, data, plan, report);
        }

        public static void TableFixedRun(
            ReadOnlySpan<TableFixedEntry> plan,
            ReadOnlySpan<byte> src,
            PartFrame dst,
            TableReport report = null,
            ReadOnlySpan<byte> planBytes = default)
        {
            TableFixedWire.Run(plan, PartFrameFixedSlots, src, dst, report, planBytes);
        }
    }

}
